public class ArrayUtils_lastIndexOf_TriageGen2Test {

    private static final int INDEX_NOT_FOUND = -1;











    @Test
    public void testLastIndexOf_FoundBeforeStartIndex() {
        boolean[] array = {true, false, true, false, false};
        // Search from index 2 (true) backwards. Last true is at index 2.
        assertEquals(2, ArrayUtils.lastIndexOf(array, true, 2));
        // Search from index 4 (false) backwards. Last true is at index 2.
        assertEquals(2, ArrayUtils.lastIndexOf(array, true, 4));
    }








}

package org.apache.commons.lang3;

import java.io.*;
