import org.apache.commons.lang3.builder.ToStringStyle;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class ArrayUtils_lastIndexOf_TriageGen2Test {

    private static final int INDEX_NOT_FOUND = -1;













    @Test
    public void testLastIndexOf_ValueNotFound() {
        boolean[] array = {true, true, false, false};
        assertEquals(INDEX_NOT_FOUND, ArrayUtils.lastIndexOf(array, true, 1)); // Only looks at index 1 and 0
        assertEquals(INDEX_NOT_FOUND, ArrayUtils.lastIndexOf(array, false, 0)); // Only looks at index 0
        assertEquals(INDEX_NOT_FOUND, ArrayUtils.lastIndexOf(array, true, 0)); // false is not in array if searching for true at 0? No, true is at 0.

        // Correct logic for Not Found:
        boolean[] array2 = {true, true, false};
        assertEquals(INDEX_NOT_FOUND, ArrayUtils.lastIndexOf(array2, false, 0)); 
    }






}

